/** How a pairing code is written: the characters it takes, how many, and how it's grouped. */
type PairingCodeFormat = {
  /** The characters a code may hold, in any case; letters and digits when unset. */
  alphabet?: string
  /** The most characters a code holds; no limit when unset. */
  length?: number
  /** Characters per visual group. */
  groupSize: number
  separator: string
}

type PairingCodeEdit = { value: string; code: string; caret: number }

/** Whether a group of the typed code matches the same group of the expected one, or isn't complete yet. */
type PairingCodeGroupMatch = "match" | "mismatch" | "pending"

const letterOrDigit = /[\p{L}\p{N}]/u

function accepts(alphabet: string | undefined, character: string) {
  return alphabet === undefined ? letterOrDigit.test(character) : alphabet.toUpperCase().includes(character)
}

/** The code's characters in upper case, without separators or anything outside `alphabet`, cut to `length`. */
function normalizePairingCode(text: string, format: Pick<PairingCodeFormat, "alphabet" | "length">) {
  const kept = Array.from(text.toUpperCase()).filter((character) => accepts(format.alphabet, character))
  return (format.length === undefined ? kept : kept.slice(0, format.length)).join("")
}

function pairingCodeGroups(code: string, groupSize: number) {
  const size = Math.max(1, Math.floor(groupSize))
  const groups: string[] = []
  for (let start = 0; start < code.length; start += size) groups.push(code.slice(start, start + size))
  return groups
}

function formatPairingCode(code: string, format: Pick<PairingCodeFormat, "groupSize" | "separator">) {
  return pairingCodeGroups(code, format.groupSize).join(format.separator)
}

/** Where the caret goes in the formatted text, after the first `count` characters of the code. */
function caretAfter(count: number, format: Pick<PairingCodeFormat, "groupSize" | "separator">) {
  if (count <= 0) return 0
  const size = Math.max(1, Math.floor(format.groupSize))
  return count + Math.floor((count - 1) / size) * format.separator.length
}

function keptBefore(text: string, caret: number, format: Pick<PairingCodeFormat, "alphabet">) {
  return Array.from(text.slice(0, caret).toUpperCase()).filter((character) => accepts(format.alphabet, character))
    .length
}

/**
 * Reformats a field after an edit: `previous` is the code before it, `text` and `caret` what the field holds after
 * it. A deletion that only removed a separator removes the character beside it instead, in the edit's direction.
 */
function editPairingCode(
  previous: string,
  text: string,
  caret: number,
  format: PairingCodeFormat,
  direction: "backward" | "forward" | undefined,
): PairingCodeEdit {
  let code = normalizePairingCode(text, format)
  let before = Math.min(keptBefore(text, caret, format), code.length)
  if (code === previous && direction !== undefined) {
    const index = direction === "backward" ? before - 1 : before
    if (index >= 0 && index < code.length) {
      code = code.slice(0, index) + code.slice(index + 1)
      before = index
    }
  }
  return { value: formatPairingCode(code, format), code, caret: caretAfter(before, format) }
}

function comparePairingCodeGroups(typed: string, expected: string, groupSize: number): PairingCodeGroupMatch[] {
  const typedGroups = pairingCodeGroups(typed, groupSize)
  return pairingCodeGroups(expected, groupSize).map((group, index) => {
    const typedGroup = typedGroups[index] ?? ""
    if (typedGroup.length < group.length) return group.startsWith(typedGroup) ? "pending" : "mismatch"
    return typedGroup === group ? "match" : "mismatch"
  })
}

export {
  caretAfter,
  comparePairingCodeGroups,
  editPairingCode,
  formatPairingCode,
  normalizePairingCode,
  pairingCodeGroups,
}
export type { PairingCodeEdit, PairingCodeFormat, PairingCodeGroupMatch }

import { announce, definePrimitive } from "@ui-sdk/core"

import { unavailable } from "@/lib/action-refusal"

/** How a person checks the code against the one on the other screen. */
type PairingCodeCompare = "confirm" | "enter"

type PairingCodeOptions = {
  /** The code as `copy` writes it, with separators. Kept out of the state, so agents read it only through `code`. */
  copyText?: string
  /** Hides the code from agents: `code` stays out of the state, and `copy` and `confirm` refuse an agent's call. */
  agentHidden?: boolean
  compare?: PairingCodeCompare
  /** Runs after the code reaches the clipboard. */
  onCopy?: (code: string) => void
  /** Runs when a person says whether the codes match, in `confirm` mode. */
  onConfirm?: (matches: boolean) => unknown
  copiedAnnouncement?: string
}

type PairingCodeState = {
  /** The code, with separators; absent while it's hidden from agents. */
  code?: string
  copied: boolean
  /** The answer given in `confirm` mode, or whether the typed code matches in `enter` mode; `null` until then. */
  matches: boolean | null
}

const COPIED_FOR = 2000

const hiddenFromAgents = "the code is hidden from agents, so a person reads and compares it"

const pairingCode = definePrimitive({
  name: "pairing-code",
  options: {
    copyText: "string",
    agentHidden: "boolean",
    compare: "string",
    onCopy: "callback",
    onConfirm: "callback",
    copiedAnnouncement: "string",
  },
  controlled: ["code", "copied", "matches"],
  state: (options: PairingCodeOptions): PairingCodeState => ({
    ...(options.agentHidden ? {} : { code: options.copyText ?? "" }),
    copied: false,
    matches: null,
  }),
  sync: (options) => (options.agentHidden ? { code: undefined } : { code: options.copyText ?? "" }),
  api: (context) => {
    let copiedTimer: ReturnType<typeof setTimeout> | undefined
    context.onDestroy(() => clearTimeout(copiedTimer))
    const hiddenFromThisCall = (event: Event | undefined) => context.options().agentHidden === true && !event

    const api = {
      /** Writes the code, with separators, to the clipboard. Resolves to `"copied"`. */
      copy(event?: Event): Promise<"copied" | false> | false {
        const call = { event }
        if (hiddenFromThisCall(event)) return unavailable("copy", `isn't available: ${hiddenFromAgents}`, call)
        const { copyText } = context.options()
        if (!copyText) return unavailable("copy", "isn't available: there is no code", call)
        const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard
        if (!clipboard) return unavailable("copy", "isn't available: the page has no clipboard access", call)
        return clipboard.writeText(copyText).then(
          () => {
            clearTimeout(copiedTimer)
            context.store.set({ copied: true })
            copiedTimer = setTimeout(() => context.store.set({ copied: false }), COPIED_FOR)
            const { copiedAnnouncement, onCopy } = context.options()
            if (copiedAnnouncement) announce(copiedAnnouncement)
            onCopy?.(copyText)
            return "copied" as const
          },
          () => unavailable("copy", "was blocked by the browser", call),
        )
      },
      /** Says whether the code matches the one on the other screen, in `confirm` mode: `true` or `false`. */
      confirm(matches: unknown, event?: Event) {
        const call = { event }
        if (context.options().compare !== "confirm") {
          return unavailable("confirm", "isn't available: this code isn't compared by confirmation", call)
        }
        if (hiddenFromThisCall(event)) return unavailable("confirm", `isn't available: ${hiddenFromAgents}`, call)
        if (typeof matches !== "boolean") {
          return unavailable("confirm", "takes true when the codes match and false when they don't", call)
        }
        context.store.set({ matches })
        context.options().onConfirm?.(matches)
        return true
      },
      /** Records whether the typed code matches, in `enter` mode. */
      setMatches(matches: boolean | null) {
        if (context.store.get().matches !== matches) context.store.set({ matches })
      },
    }
    return api
  },
  slots: (slot) => ({
    root: slot<{}, PairingCodeState>({
      state: (state) => ({ ...state }),
      attrs: (state) => ({
        role: "group",
        "data-copied": state.copied ? "" : undefined,
        "data-matches": state.matches === null ? undefined : String(state.matches),
      }),
    }),
  }),
  agent: { actions: ["copy", "confirm"] },
})

export { pairingCode }
export type { PairingCodeCompare, PairingCodeOptions, PairingCodeState }

"use client"

import { useState, type ReactNode } from "react"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Field, FieldDescription, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  editPairingCode,
  formatPairingCode,
  normalizePairingCode,
  type PairingCodeFormat,
} from "@/components/ui/pairing-code-format"
import { cn } from "@/lib/utils"

type PairingCodeSize = "default" | "lg"

type PairingCodeInputProps = {
  /** The field's visible label, which names it for screen readers and agents. */
  label: ReactNode
  /** How many characters a full code has. */
  length: number
  /** The characters a code may hold, in any case; others are dropped as they're typed or pasted. Letters and digits by default. */
  alphabet?: string
  /** Characters per visual group; 4 by default. */
  groupSize?: number
  /** Inserted between groups as the person types; "-" by default. */
  separator?: string
  /** The code, normalized, for a controlled field. */
  value?: string
  defaultValue?: string
  /** Runs with the normalized code, without separators, on every change. */
  onChange?: (code: string) => void
  /** Runs with the normalized code each time an edit makes it full. */
  onComplete?: (code: string) => void
  /** Makes the field read-only and busy, like while the code is looked up. */
  pending?: boolean
  /** Shown in a live alert under the field, which is marked invalid. */
  error?: ReactNode
  description?: ReactNode
  /** Keeps the field from agents: they can't read or type the code. */
  agentHidden?: boolean
  size?: PairingCodeSize
  name?: string
  placeholder?: string
  className?: string
}

function deletionDirection(event: Event | undefined) {
  const inputType = event && "inputType" in event && typeof event.inputType === "string" ? event.inputType : ""
  if (inputType.startsWith("deleteContentBackward") || inputType === "deleteWordBackward") return "backward"
  if (inputType.startsWith("deleteContentForward") || inputType === "deleteWordForward") return "forward"
  return undefined
}

function hasContent(node: ReactNode) {
  return node !== undefined && node !== null && node !== false
}

function PairingCodeInput({
  label,
  length,
  alphabet,
  groupSize = 4,
  separator = "-",
  value,
  defaultValue,
  onChange,
  onComplete,
  pending = false,
  error,
  description,
  agentHidden = false,
  size = "default",
  name,
  placeholder,
  className,
}: PairingCodeInputProps) {
  const format: PairingCodeFormat = { alphabet, length, groupSize, separator }
  const [ownCode, setOwnCode] = useState(() => normalizePairingCode(defaultValue ?? "", format))
  const code = value === undefined ? ownCode : normalizePairingCode(value, format)
  const formatted = formatPairingCode(code, format)
  const invalid = hasContent(error)

  const change = (next: string) => {
    if (next === code) return
    if (value === undefined) setOwnCode(next)
    onChange?.(next)
    if (next.length === length) onComplete?.(next)
  }

  return (
    <div
      data-slot="pairing-code-input"
      data-agent-hidden={agentHidden ? "" : undefined}
      data-complete={code.length === length ? "" : undefined}
      className={cn("flex min-w-0 flex-col", className)}
    >
      <Field invalid={invalid ? true : undefined}>
        <FieldLabel>{label}</FieldLabel>
        <Input
          name={name}
          value={formatted}
          placeholder={placeholder}
          readOnly={pending}
          aria-busy={pending ? true : undefined}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="characters"
          spellCheck={false}
          inputMode="text"
          translate="no"
          className={size === "lg" ? "h-control-lg font-mono text-title tracking-wider" : "font-mono tracking-wider"}
          onValueChange={(text, details) => {
            const field = details.event?.target instanceof HTMLInputElement ? details.event.target : null
            const edit = editPairingCode(
              code,
              text,
              field?.selectionStart ?? text.length,
              format,
              deletionDirection(details.event),
            )
            if (edit.code === code && edit.value === formatted) {
              details.cancel()
              return
            }
            if (field) {
              field.value = edit.value
              field.setSelectionRange(edit.caret, edit.caret)
            }
            change(edit.code)
          }}
        />
        {hasContent(description) ? <FieldDescription>{description}</FieldDescription> : null}
        {invalid ? (
          <FieldError
            match
            render={(props) => (
              <Alert {...props} data-slot="pairing-code-input-error" tone="destructive" live>
                <AlertDescription className="text-foreground">{error}</AlertDescription>
              </Alert>
            )}
          />
        ) : null}
      </Field>
    </div>
  )
}

export { PairingCodeInput }
export type { PairingCodeInputProps, PairingCodeSize }

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { CheckIcon, CircleDashedIcon, CopyIcon, XIcon } from "lucide-react"
import { useState, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { PairingCodeInput, type PairingCodeInputProps, type PairingCodeSize } from "@/components/ui/pairing-code-input"
import {
  comparePairingCodeGroups,
  formatPairingCode,
  normalizePairingCode,
  pairingCodeGroups,
  type PairingCodeGroupMatch,
} from "@/components/ui/pairing-code-format"
import { pairingCode, type PairingCodeCompare, type PairingCodeState } from "@/components/ui/pairing-code-primitive"
import { cn } from "@/lib/utils"

/** Names and announcements for screen readers and agents; English by default. */
type PairingCodeLabels = {
  copy: string
  copied: string
  copiedAnnouncement: string
  /** What a screen reader reads for the code, from its groups: "B C D F, G H J K" by default. */
  spell: (groups: readonly string[]) => string
}

const pairingCodeLabels: PairingCodeLabels = {
  copy: "Copy code",
  copied: "Copied",
  copiedAnnouncement: "Code copied",
  spell: (groups) => groups.map((group) => Array.from(group).join(" ")).join(", "),
}

/** The `confirm` mode's text. None has a default: pass it in the page's language. */
type PairingCodeConfirmText = {
  /** Above the answers, like "Does this code match the one on your device?" */
  prompt?: ReactNode
  matches: ReactNode
  mismatch: ReactNode
}

/** The `enter` mode's text. None has a default: pass it in the page's language. */
type PairingCodeEnterText = {
  /** The field's label, like "Code shown on your device". */
  label: ReactNode
  description?: ReactNode
  /** Shown, and read, once the typed code matches. */
  matches: ReactNode
  /** Shown, and read, while a typed group differs. */
  mismatch: ReactNode
}

type PairingCodeBaseProps = {
  /** The code, with or without separators, in any case. */
  code: string
  /** Names the code for screen readers and agents, like "Pairing code". */
  label: string
  /** Characters per visual group; 4 by default. */
  groupSize?: number
  /** Shown between groups and copied with the code; "-" by default. */
  separator?: string
  size?: PairingCodeSize
  /** Keeps the code from agents: they can't read, copy or compare it, while a person can. */
  agentHidden?: boolean
  /** Runs once the code, with separators, is on the clipboard. */
  onCopy?: (code: string) => void
  labels?: Partial<PairingCodeLabels>
  className?: string
}

type PairingCodeCompareProps =
  | { compare?: undefined; text?: undefined }
  | {
      /** Asks the person whether the code matches the one on the other screen. */
      compare: "confirm"
      text: PairingCodeConfirmText
      onConfirm?: (matches: boolean) => unknown
    }
  | {
      /** Asks the person to type the other screen's code, and checks it group by group as they type. */
      compare: "enter"
      text: PairingCodeEnterText
      /** Runs when the typed code starts or stops matching. */
      onMatchChange?: (matches: boolean) => void
    }

type PairingCodeProps = PairingCodeBaseProps & PairingCodeCompareProps

const rootAttributes = (size: PairingCodeSize): Record<`data-${string}`, string> => ({
  "data-slot": "pairing-code",
  "data-size": size,
})

const valueSize: Record<PairingCodeSize, string> = { default: "text-display-sm", lg: "text-display" }

const groupTone: Record<PairingCodeGroupMatch, string> = {
  match: "border-success-border bg-success-soft text-success-soft-foreground",
  mismatch: "border-destructive-border bg-destructive-soft text-destructive-soft-foreground",
  pending: "border-border text-foreground",
}

const groupIcon: Record<PairingCodeGroupMatch, ReactNode> = {
  match: <CheckIcon strokeWidth={2.5} />,
  mismatch: <XIcon strokeWidth={2.5} />,
  pending: <CircleDashedIcon />,
}

type CodeGroup = { start: number; text: string; match: PairingCodeGroupMatch | undefined }

function hasContent(node: ReactNode) {
  return node !== undefined && node !== null && node !== false
}

function CodeValue({
  groups,
  separator,
  size,
  agentHidden,
  spoken,
}: {
  groups: readonly CodeGroup[]
  separator: string
  size: PairingCodeSize
  agentHidden: boolean
  spoken: string
}) {
  return (
    <span
      data-slot="pairing-code-value"
      data-agent-hidden={agentHidden ? "" : undefined}
      translate="no"
      className={cn("min-w-0 font-mono tracking-wider", valueSize[size])}
    >
      <span aria-hidden="true" className="flex flex-wrap items-center gap-inline">
        {groups.map((group, index) => (
          <span key={group.start} className="flex items-center gap-inline">
            {index > 0 ? (
              <span data-slot="pairing-code-separator" className="text-muted-foreground">
                {separator}
              </span>
            ) : null}
            <span
              data-slot="pairing-code-group"
              data-match={group.match}
              className={cn(
                "flex items-center gap-inline rounded-control",
                group.match === undefined
                  ? undefined
                  : `border px-inset-chip transition-colors duration-micro ease-standard ${groupTone[group.match]}`,
              )}
            >
              {group.text}
              {group.match === undefined ? null : (
                <span data-slot="pairing-code-group-state" className="[&_svg]:size-4">
                  {groupIcon[group.match]}
                </span>
              )}
            </span>
          </span>
        ))}
      </span>
      <span className="sr-only">{spoken}</span>
    </span>
  )
}

function ConfirmAnswers({
  text,
  matches,
  agentHidden,
  onAnswer,
}: {
  text: PairingCodeConfirmText
  matches: boolean | null
  agentHidden: boolean
  onAnswer: (matches: boolean, event: Event) => void
}) {
  return (
    <div
      data-slot="pairing-code-confirm"
      data-agent-hidden={agentHidden ? "" : undefined}
      className="flex flex-col gap-items"
    >
      {hasContent(text.prompt) ? <p className="text-body text-muted-foreground">{text.prompt}</p> : null}
      <div className="flex flex-wrap gap-items narrow:flex-col">
        <Button
          variant={matches === true ? "default" : "outline"}
          onClick={(event) => onAnswer(true, event.nativeEvent)}
        >
          <CheckIcon />
          {text.matches}
        </Button>
        <Button
          variant={matches === false ? "destructive" : "outline"}
          onClick={(event) => onAnswer(false, event.nativeEvent)}
        >
          <XIcon />
          {text.mismatch}
        </Button>
      </div>
    </div>
  )
}

function MatchStatus({ text, matches }: { text: PairingCodeEnterText; matches: boolean | null }) {
  return (
    <output
      data-slot="pairing-code-match"
      data-matches={matches === null ? undefined : String(matches)}
      className="flex min-h-(--type-body-leading) items-center gap-inline text-body data-[matches=false]:text-destructive-soft-foreground data-[matches=true]:text-success-soft-foreground [&_svg]:size-4"
    >
      {matches === true ? (
        <>
          <CheckIcon strokeWidth={2.5} />
          {text.matches}
        </>
      ) : null}
      {matches === false ? (
        <>
          <XIcon strokeWidth={2.5} />
          {text.mismatch}
        </>
      ) : null}
    </output>
  )
}

function enterMatch(groups: readonly PairingCodeGroupMatch[]) {
  if (groups.every((group) => group === "match")) return true
  return groups.includes("mismatch") ? false : null
}

function PairingCode(props: PairingCodeProps) {
  const {
    code: rawCode,
    label,
    groupSize = 4,
    separator = "-",
    size = "default",
    agentHidden = false,
    onCopy,
    labels: overrides,
    className,
  } = props
  const labels = { ...pairingCodeLabels, ...overrides }
  const code = normalizePairingCode(rawCode, {})
  const format = { groupSize, separator }
  const [typed, setTyped] = useState("")
  const groupMatches = props.compare === "enter" ? comparePairingCodeGroups(typed, code, groupSize) : undefined
  const groupTexts = pairingCodeGroups(code, groupSize)
  const groupLength = Math.max(1, Math.floor(groupSize))
  const groups = groupTexts.map((text, index) => ({ start: index * groupLength, text, match: groupMatches?.[index] }))
  const handle = usePrimitive(pairingCode, {
    copyText: formatPairingCode(code, format),
    agentHidden,
    compare: props.compare,
    onCopy,
    onConfirm: props.compare === "confirm" ? props.onConfirm : undefined,
    copiedAnnouncement: labels.copiedAnnouncement,
  })
  const { api } = handle

  const typeCode = (next: string) => {
    setTyped(next)
    if (props.compare !== "enter") return
    const wasMatching = typed === code
    const matching = next === code
    api.setMatches(enterMatch(comparePairingCodeGroups(next, code, groupSize)))
    if (wasMatching !== matching) props.onMatchChange?.(matching)
  }

  return usePart(
    handle,
    "root",
    {},
    {
      ...rootAttributes(size),
      "aria-label": label,
      className: cn("flex min-w-0 flex-col gap-items", className),
      children: (state: PairingCodeState) => (
        <>
          <div className="flex min-w-0 items-center gap-items">
            <CodeValue
              groups={groups}
              separator={separator}
              size={size}
              agentHidden={agentHidden}
              spoken={labels.spell(groupTexts)}
            />
            <span data-agent-hidden={agentHidden ? "" : undefined} className="contents">
              <Button
                size="icon"
                variant="ghost"
                aria-label={state.copied ? labels.copied : labels.copy}
                onClick={(event) => {
                  const copied = api.copy(event.nativeEvent)
                  if (copied) copied.then(undefined, () => undefined)
                }}
              >
                {state.copied ? <CheckIcon /> : <CopyIcon />}
              </Button>
            </span>
          </div>
          {props.compare === "confirm" ? (
            <ConfirmAnswers
              text={props.text}
              matches={state.matches}
              agentHidden={agentHidden}
              onAnswer={(matches, event) => api.confirm(matches, event)}
            />
          ) : null}
          {props.compare === "enter" ? (
            <div data-slot="pairing-code-enter" className="flex flex-col gap-inline">
              <PairingCodeInput
                label={props.text.label}
                description={props.text.description}
                length={code.length}
                groupSize={groupSize}
                separator={separator}
                size={size}
                agentHidden={agentHidden}
                value={typed}
                onChange={typeCode}
              />
              <MatchStatus text={props.text} matches={state.matches} />
            </div>
          ) : null}
        </>
      ),
    },
  )
}

export { PairingCode, PairingCodeInput, pairingCodeLabels }
export type {
  PairingCodeCompare,
  PairingCodeConfirmText,
  PairingCodeEnterText,
  PairingCodeInputProps,
  PairingCodeLabels,
  PairingCodeProps,
  PairingCodeSize,
}
